import os,glob,re
def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load(); print(sorted(G))

from collections import deque
def transform(g):
    h,w=len(g),len(g[0])
    seen=[[False]*w for _ in range(h)]
    out=[row[:] for row in g]
    for i in range(h):
        for j in range(w):
            if g[i][j] and not seen[i][j]:
                comp=[]; q=deque([(i,j)]); seen[i][j]=True
                while q:
                    y,x=q.popleft(); comp.append((y,x))
                    for dy,dx in((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<h and 0<=nx<w and not seen[ny][nx] and g[ny][nx]:
                            seen[ny][nx]=True; q.append((ny,nx))
                order=[]
                for y,x in comp:
                    if g[y][x] not in order: order.append(g[y][x])
                m=dict(zip(order,order[::-1]))
                for y,x in comp: out[y][x]=m[g[y][x]]
    return out
print(transform(G['Demo pair 1 input'])==G['Demo pair 1 output'])
